begin;
select no_plan();

-- AR-001--005, 010, 048, 109--115, 118, 126, 129--131, 140, 153: exact boundary.
select has_table('bios_knowledge','evidence','AR-001/002 Evidence table exists');
select has_table('bios_knowledge','evidence_provenance','AR-002 provenance table exists');
select results_eq($$select count(*)::bigint from pg_tables where schemaname='bios_knowledge' and tablename in ('evidence','evidence_provenance')$$,array[2::bigint],'AR-002 exactly two M006 tables');
select is_empty($$select 1 from information_schema.tables where table_schema like 'bios_%' and table_name in ('evidence_types','evidence_links','evidence_versions','evidence_anchors','evidence_representations','representations','document_representations','extraction_runs','extractions','ingestion_jobs','signals','patterns','findings','recommendations','decision_contexts','decisions','vectors','embeddings')$$,'AR-004/111/112/118/130/153 deferred structures absent');
select results_eq($$select (select count(*) from bios_knowledge.evidence)+(select count(*) from bios_knowledge.evidence_provenance)$$,array[0::bigint],'AR-005 zero seeds');
select is_empty($$select 1 from information_schema.columns where table_schema='bios_knowledge' and table_name in ('evidence','evidence_provenance') and column_name in ('value','unit','confidence','reliability','truth','importance','impact','trend','implication','recommendation','market_id','geography_id','domain_id','domain_node_id','entity_id','representation_id','extraction_run_id','model_id','generation_method','actor_identifier','correlation_id','purpose','target_tenant_id','metadata','resource_type','resource_id')$$,'AR-010/022/048/110/112/131/140 prohibited columns absent');
select is_empty($$select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='bios_internal' and p.proname ~ '(entitlement|reader|purpose.*author|service.*capability|representation|extract|ocr|translat|ingest|connector)'$$,'AR-109/118/126/130/153 no reader, entitlement, or automation function');

-- Synthetic foundation fixtures.
insert into bios_core.tenants(id,code,name,status,activated_at) values
 ('b6000000-0000-0000-0000-000000000001','evidence_tenant_a','Evidence Tenant A','active',statement_timestamp()),
 ('b6000000-0000-0000-0000-000000000002','evidence_tenant_b','Evidence Tenant B','active',statement_timestamp());
insert into bios_core.languages(id,tag,base_language_subtag,display_name,status,activated_at) values ('b6100000-0000-0000-0000-000000000001','ev','ev','Evidence Language','active',statement_timestamp());
insert into bios_knowledge.sources(id,code,canonical_name,knowledge_scope,status,activated_at) values ('b6200000-0000-0000-0000-000000000001','evidence_shared','Evidence Shared','shared','active',statement_timestamp());
insert into bios_knowledge.sources(id,code,canonical_name,knowledge_scope,tenant_id,status,activated_at) values
 ('b6200000-0000-0000-0000-000000000002','evidence_private_a','Evidence Private A','tenant','b6000000-0000-0000-0000-000000000001','active',statement_timestamp());
insert into bios_knowledge.source_documents(id,source_id,knowledge_scope,tenant_id,canonical_title,access_classification) values
 ('b6300000-0000-0000-0000-000000000001','b6200000-0000-0000-0000-000000000001','shared',null,'Shared Public','public'),
 ('b6300000-0000-0000-0000-000000000002','b6200000-0000-0000-0000-000000000001','shared',null,'Shared Licensed','licensed'),
 ('b6300000-0000-0000-0000-000000000003','b6200000-0000-0000-0000-000000000001','shared',null,'Shared Restricted','restricted'),
 ('b6300000-0000-0000-0000-000000000004','b6200000-0000-0000-0000-000000000002','tenant','b6000000-0000-0000-0000-000000000001','Private A','tenant_confidential');
update bios_knowledge.source_documents set status='active',activated_at=statement_timestamp() where id in ('b6300000-0000-0000-0000-000000000001','b6300000-0000-0000-0000-000000000002','b6300000-0000-0000-0000-000000000003','b6300000-0000-0000-0000-000000000004');
select set_config('request.jwt.claims','{"role":"service_role"}',true);

-- AR-006--014, 041--057: field and anchor constraints.
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,evidence_text,text_kind,language_id,access_classification) values('shared',' ','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public')$$,'23514',null,'AR-007 Evidence text trim/nonempty');
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,evidence_text,text_kind,language_id,access_classification) values('shared',repeat('x',2001),'verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public')$$,'23514',null,'AR-007 Evidence text bound');
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,evidence_text,text_kind,language_id,access_classification) values('shared','x','analysis','b6100000-0000-0000-0000-000000000001','public')$$,'23514',null,'AR-009 exact text_kind');
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,evidence_text,text_kind,language_id,access_classification) values('global','x','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public')$$,'23514',null,'AR-011 exact scope');
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,tenant_id,evidence_text,text_kind,language_id,access_classification) values('shared','b6000000-0000-0000-0000-000000000001','x','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public')$$,'23514',null,'AR-012 scope Tenant invariant');
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,evidence_text,text_kind,language_id,access_classification,valid_to) values('shared','x','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',now())$$,'23514',null,'AR-053 valid_to requires valid_from');
select throws_ok($$insert into bios_knowledge.evidence(knowledge_scope,evidence_text,text_kind,language_id,access_classification,valid_from,valid_to) values('shared','x','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',now(),now())$$,'23514',null,'AR-054 ordered validity');

-- AR-015--40, 49--85, 96, 119--123, 127--128, 132--152: governed creation/security.
select lives_ok($$select bios_internal.create_evidence('shared',null,'Shared evidence','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,null,'b6300000-0000-0000-0000-000000000001','document',null,null,null,null,null,null,null,null,'evidence-service','corr-shared','manual governed creation')$$,'AR-015/023/127/142 atomic shared/public creation');
select results_eq($$select status from bios_knowledge.evidence where evidence_text='Shared evidence'$$,array['candidate'],'AR-014 creation starts candidate');
select results_eq($$select count(*)::bigint from bios_knowledge.evidence_provenance where evidence_id=(select id from bios_knowledge.evidence where evidence_text='Shared evidence')$$,array[1::bigint],'AR-015--21 exactly one provenance');
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind) select id,'b6300000-0000-0000-0000-000000000001','document' from bios_knowledge.evidence where evidence_text='Shared evidence'$$,'23505',null,'AR-019 second provenance rejected');
select lives_ok($$select bios_internal.create_evidence('tenant','b6000000-0000-0000-0000-000000000001','Private evidence','normalized_statement','b6100000-0000-0000-0000-000000000001','tenant_confidential',null,null,null,'b6300000-0000-0000-0000-000000000004','section',null,null,'Section 1',null,null,null,null,null,'evidence-service','corr-private','manual governed creation')$$,'AR-029/143 same-Tenant private confidential succeeds');
select throws_ok($$select bios_internal.create_evidence('tenant',null,'Missing tenant','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','tenant_confidential',null,null,null,'b6300000-0000-0000-0000-000000000004','document',null,null,null,null,null,null,null,null,'evidence-service','corr-x','purpose')$$,'P0001','same-Tenant tenant-confidential provenance required','AR-144 missing target Tenant rejected');
select throws_ok($$select bios_internal.create_evidence('tenant','b6000000-0000-0000-0000-000000000002','Mismatch','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','tenant_confidential',null,null,null,'b6300000-0000-0000-0000-000000000004','document',null,null,null,null,null,null,null,null,'evidence-service','corr-x','purpose')$$,'P0001','same-Tenant tenant-confidential provenance required','AR-030/122/145/152 cross-Tenant rejected');
select throws_ok($$select bios_internal.create_evidence('tenant','b6000000-0000-0000-0000-000000000001','Licensed','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','licensed',null,null,null,'b6300000-0000-0000-0000-000000000002','document',null,null,null,null,null,null,null,null,'evidence-service','corr-license','licensed purpose')$$,'P0001','shared licensed or restricted provenance is not authorized','AR-027/146/148--151 licensed rejected despite context');
select throws_ok($$select bios_internal.create_evidence('tenant','b6000000-0000-0000-0000-000000000001','Restricted','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','restricted',null,null,null,'b6300000-0000-0000-0000-000000000003','document',null,null,null,null,null,null,null,null,'evidence-service','corr-restrict','restricted purpose')$$,'P0001','shared licensed or restricted provenance is not authorized','AR-028/147--151 restricted rejected despite context');
select throws_ok($$select bios_internal.create_evidence('shared',null,'Private to shared','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,null,'b6300000-0000-0000-0000-000000000004','document',null,null,null,null,null,null,null,null,'evidence-service','corr-x','purpose')$$,'P0001','same-Tenant tenant-confidential provenance required','AR-024/034 shared from private rejected');
select throws_ok($$select bios_internal.create_evidence('shared',null,'No actor','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,null,'b6300000-0000-0000-0000-000000000001','document',null,null,null,null,null,null,null,null,null,'corr','purpose')$$,'P0001',null,'AR-096/137 actor required');
select throws_ok($$select bios_internal.create_evidence('shared',null,'No correlation','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,null,'b6300000-0000-0000-0000-000000000001','document',null,null,null,null,null,null,null,null,'evidence-service',null,'purpose')$$,'P0001','invalid correlation_id','AR-132 correlation required');
select throws_ok($$select bios_internal.create_evidence('shared',null,'No purpose','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,null,'b6300000-0000-0000-0000-000000000001','document',null,null,null,null,null,null,null,null,'evidence-service','corr',null)$$,'P0001','invalid purpose','AR-134 purpose required');
select lives_ok($$select bios_internal.update_evidence_candidate((select id from bios_knowledge.evidence where evidence_text='Shared evidence'),'Shared evidence corrected','normalized_statement','b6100000-0000-0000-0000-000000000001','restricted',now(),null,'evidence-service','corr-correct','factual candidate correction')$$,'AR-058/059/103 candidate correction and audit');
select lives_ok($$select bios_internal.transition_evidence((select id from bios_knowledge.evidence where evidence_text='Shared evidence corrected'),'active','evidence-service','corr-activate','manual validation')$$,'AR-049/064 activation revalidates provenance and Language');
select throws_ok($$select bios_internal.update_evidence_candidate((select id from bios_knowledge.evidence where evidence_text='Shared evidence corrected'),'rewrite','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,'evidence-service','corr-x','purpose')$$,'P0001','only candidate Evidence is correctable','AR-061/063 active material immutable');
select lives_ok($$select bios_internal.create_evidence('shared',null,'Successor evidence','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,(select id from bios_knowledge.evidence where evidence_text='Shared evidence corrected'),'b6300000-0000-0000-0000-000000000001','page',1,2,null,null,null,null,null,null,'evidence-service','corr-successor','material correction')$$,'AR-063/072--78 successor proposal and deterministic lock');
select throws_ok($$select bios_internal.create_evidence('shared',null,'Second successor','verbatim_excerpt','b6100000-0000-0000-0000-000000000001','public',null,null,(select id from bios_knowledge.evidence where evidence_text='Shared evidence corrected'),'b6300000-0000-0000-0000-000000000001','document',null,null,null,null,null,null,null,null,'evidence-service','corr-successor2','second proposal')$$,'23505',null,'AR-076/077 one candidate successor');
select lives_ok($$select bios_internal.transition_evidence((select id from bios_knowledge.evidence where evidence_text='Successor evidence'),'active','evidence-service','corr-supersede','approve revision')$$,'AR-080--82 atomic supersession');
select results_eq($$select status from bios_knowledge.evidence where evidence_text='Shared evidence corrected'$$,array['superseded'],'AR-080/081 predecessor superseded');

-- AR-041--47 anchor constraints by direct catalog enforcement.
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind,page_start) values(gen_random_uuid(),'b6300000-0000-0000-0000-000000000001','page',1)$$,'23503',null,'AR-016/020 provenance requires Evidence');
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind,page_start) select id,'b6300000-0000-0000-0000-000000000001','page',0 from bios_knowledge.evidence where evidence_text='Private evidence'$$,'23514',null,'AR-042 page bound');
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind,section_label) select id,'b6300000-0000-0000-0000-000000000001','section',' ' from bios_knowledge.evidence where evidence_text='Private evidence'$$,'23514',null,'AR-043 section bound');
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind,line_start,line_end) select id,'b6300000-0000-0000-0000-000000000001','line_range',2,1 from bios_knowledge.evidence where evidence_text='Private evidence'$$,'23514',null,'AR-044 line ordering');
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind,time_start_ms,time_end_ms) select id,'b6300000-0000-0000-0000-000000000001','time_range',2,1 from bios_knowledge.evidence where evidence_text='Private evidence'$$,'23514',null,'AR-045 time ordering');
select throws_ok($$insert into bios_knowledge.evidence_provenance(evidence_id,source_document_id,anchor_kind,source_native_locator) select id,'b6300000-0000-0000-0000-000000000001','source_native',' ' from bios_knowledge.evidence where evidence_text='Private evidence'$$,'23514',null,'AR-046 native locator bound');

-- AR-086--108, 113--117, 124--125, 138--139: RLS, grants, audit and history.
select results_eq($$select count(*)::bigint from pg_policies where schemaname='bios_knowledge' and tablename in ('evidence','evidence_provenance')$$,array[2::bigint],'AR-086--94 RLS policies installed');
select ok(not has_table_privilege('anon','bios_knowledge.evidence','select') and not has_table_privilege('anon','bios_knowledge.evidence_provenance','select'),'AR-086/087 anonymous denied');
select ok(not has_table_privilege('authenticated','bios_knowledge.evidence','insert') and not has_table_privilege('authenticated','bios_knowledge.evidence','update') and not has_table_privilege('authenticated','bios_knowledge.evidence','delete'),'AR-095/099 direct mutation denied');
select ok(not has_function_privilege('authenticated','bios_internal.create_evidence(text,uuid,text,text,uuid,text,timestamptz,timestamptz,uuid,uuid,text,integer,integer,text,integer,integer,bigint,bigint,text,text,text,text)','execute'),'AR-095/120 ordinary execution denied');
select results_eq($$select count(*)::bigint from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='bios_internal' and p.proname in ('create_evidence','update_evidence_candidate','transition_evidence') and p.prosecdef and p.proconfig=array['search_path=""']$$,array[3::bigint],'AR-097 fixed empty search_path');
select results_eq($$select count(*)::bigint from bios_governance.audit_events where resource_type in ('evidence','evidence_provenance') and action not in ('reference.created','reference.status_changed','reference.metadata_updated')$$,array[0::bigint],'AR-101--105 approved audit vocabulary only');
select is_empty($$select 1 from bios_governance.audit_events where resource_type in ('evidence','evidence_provenance') and (metadata ? 'evidence_text' or metadata ? 'content' or metadata ? 'excerpt' or metadata ? 'token' or metadata ? 'secret')$$,'AR-106/107/138/139 safe bounded audit metadata');
select throws_ok($$delete from bios_knowledge.evidence where evidence_text='Private evidence'$$,'P0001','Evidence foundation rows cannot be deleted','AR-100 physical deletion denied');
select ok((select count(*)=20 from pg_tables where (schemaname,tablename) in (('bios_core','profiles'),('bios_core','tenants'),('bios_core','tenant_memberships'),('bios_core','roles'),('bios_core','membership_roles'),('bios_governance','audit_events'),('bios_core','geographies'),('bios_core','geography_relationships'),('bios_core','markets'),('bios_core','market_geographies'),('bios_core','market_groups'),('bios_core','market_group_members'),('bios_core','languages'),('bios_core','market_languages'),('bios_core','domains'),('bios_core','domain_nodes'),('bios_core','domain_node_relationships'),('bios_knowledge','entity_types'),('bios_knowledge','entities'),('bios_knowledge','entity_aliases'))),'AR-113/114 M001--004 catalog preserved');
select ok((select count(*)=2 from pg_tables where schemaname='bios_knowledge' and tablename in ('sources','source_documents')),'AR-113 M005 catalog preserved');
select ok((select count(*)>=2 from bios_knowledge.evidence) and (select count(*)>=2 from bios_knowledge.evidence_provenance),'AR-037--40/085/117/125 historical rows and provenance retained');

select * from finish();
rollback;
